module Program

open ContractModel

let mutable checks = 0
let eq label expected actual =
    checks <- checks + 1
    if expected <> actual then failwithf "%s: expected %A; got %A" label expected actual

let bools = [false; true]
// Literal oracle rows from parent spec v2, not generated by the model.
let rows =
    [ NoOperativeWait, Idle, true
      ExactPending, Blocked, false
      ExactSatisfied, Blocked, false
      Missing, Idle, false
      Corrupt, Idle, false
      Partial, Idle, false
      Cancelled, Idle, false ]

let states =
    [ for wait, idleLabel, waitAllows in rows do
        for active in bools do
            for historical in bools do
                for held in bools do
                    for role in bools do
                        for demand in bools do
                            for flight in bools do
                                let s =
                                    { initial with Wait = wait; Active = active; HistoricalBlocked = historical
                                                   Held = held; RoleEligible = role; Runnable = demand; InFlight = flight }
                                let label = if active then Working else idleLabel
                                let dispatch = waitAllows && not active && not held && role && demand && not flight
                                yield s, label, dispatch ]

let send op cmd s = apply (request op cmd s) s

let truthTable () =
    for s, label, dispatch in states do
        eq "projection" label (projection s)
        eq "dispatch" dispatch (canDispatch s)
        eq "observation purity" s (send 1 Observe s)
        let activation = send 1 OwnCall s
        eq "ordinary call never bypasses wait" (s.Active || s.Wait = NoOperativeWait) activation.Active
        let launch = send 2 Launch s
        eq "launch count" (if dispatch then 1 else 0) launch.Launches
        eq "launch is not activation" s.Active launch.Active
        let wake = send 3 Wake s
        let allowed = not s.Active && s.Wait = ExactSatisfied && not s.Held
        eq "only exact satisfied wait requeues" (if allowed then 1 else 0) wake.Requeues
        eq "wake not activation" s.Active wake.Active
        eq "wake preserves hold" s.Held wake.Held
        if not allowed then eq "negative wake is inert" s wake

let traces () =
    // Competing operations were read at the same version; test both serializations.
    let commands =
        [ OwnCall; Finish; RecoverVerified; RecoverUnverified; YieldChallenge
          Wake; Launch; Observe; AttributeLaunch ]
    for s, _, _ in states do
        for a in commands do
            for b in commands do
                let ra, rb = request 1 a s, request 2 b s
                let afterA = apply ra s
                let afterB = apply rb s
                for first, second, afterFirst in [ra, rb, afterA; rb, ra, afterB] do
                    let final = apply second afterFirst
                    if afterFirst.Version <> s.Version then
                        eq "losing stale CAS cannot mutate" afterFirst final
                    eq "duplicate exact request" final (apply first final)
                    eq "stale generation even at current version" final
                        (apply { second with Version = final.Version; Generation = final.Generation - 1 } final)
                    eq "observation preserves all state" final (send 3 Observe final)
                    if final.Requeues > 1 || final.Launches > 1 then
                        failwith "same-version pair duplicated a requeue or launch"

let scenarios () =
    let active = send 1 OwnCall { initial with Runnable = false }
    eq "taskless registered call activates" Working (projection active)
    eq "normal terminal releases" Idle (projection (send 2 Finish active))
    eq "unverified recovery inert" active (send 3 RecoverUnverified active)
    eq "verified recovery releases" Idle (projection (send 3 RecoverVerified active))
    let withWait = { active with Wait = ExactPending; HistoricalBlocked = true }
    eq "historical blocked does not mask working" Working (projection withWait)
    let blocked = send 4 YieldChallenge withWait
    eq "challenge yield releases inference" Blocked (projection blocked)
    eq "ordinary call cannot resume blocked" blocked (send 5 OwnCall blocked)
    let satisfied = { blocked with Wait = ExactSatisfied; Version = blocked.Version + 1; Runnable = true }
    let wake = send 6 Wake satisfied
    eq "requeue yields idle" Idle (projection wake)
    eq "eligible after wake" true (canDispatch wake)
    eq "fresh repeat wake cannot requeue twice" wake (send 7 Wake wake)
    let flight = send 8 Launch wake
    eq "launch flight stays idle" Idle (projection flight)
    eq "no duplicate flight" flight (send 9 Launch flight)
    let resumed = send 10 OwnCall flight
    eq "activity begins turn" Working (projection resumed)
    eq "attribution clears flight" false (send 11 AttributeLaunch resumed).InFlight
    eq "STOP separate from state" Idle (projection { initial with Held = true })
    eq "STOP forbids dispatch" false (canDispatch { initial with Held = true })
    eq "history alone cannot prevent dispatch" true (canDispatch { initial with HistoricalBlocked = true })

[<EntryPoint>]
let main _ =
    truthTable ()
    traces ()
    scenarios ()
    printfn "Contract model only: %d generated states; %d assertions passed." states.Length checks
    0
